<template>
  <div class="lab-home">
    <!-- 顶部标题栏 -->
    <header class="lab-header">
      <h1>许墨的私人实验室</h1>
    </header>

    <!-- 头像和欢迎语区域 -->
    <section class="welcome-section">
      <img class="avatar" src="@/assets/xumo-avatar.jpg" alt="许墨头像" />
      <p class="welcome-text">欢迎回来，今天也来找我了吗？</p>
    </section>

    <!-- 功能按钮区域 -->
    <section class="action-buttons">
      <el-button class="action-btn" round @click="showMessage">💬 留言</el-button>
      <el-button class="action-btn" round @click="playVoice">🔊 语音</el-button>
    </section>
    <!--  留言弹窗  -->
    <el-dialog
        title="来自许墨的留言"
        :visible.sync="dialogVisible"
        width="80%"
        :close-on-click-modal="false"
    >
      <p class="message-text">{{ todayMessage.text }}</p>
      <audio :src="todayMessage.audio" ref="msgAudio" autoplay></audio>

      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">关闭</el-button>
      </span>
    </el-dialog>

    <!-- 底部装饰背景 -->
    <footer class="footer-background">
<!--      <div class="wave"></div>-->
    </footer>
  </div>
</template>

<script>
import { messages } from '@/assets/messageData.js';
export default {
  name: 'LabHome',
  data() {
    return {
      dialogVisible: false,
      todayMessage: {
        text: '',
        audio: ''
      }
    };
  },
  methods: {
    showMessage() {
      const index = this.getTodayIndex(messages.length);
      this.todayMessage = messages[index];
      this.dialogVisible = true;
      this.$nextTick(() => {
        this.$refs.msgAudio.load(); // 重载音频
        this.$refs.msgAudio.play();
      });
    },
    getTodayIndex(total) {
      const today = new Date().toISOString().slice(0, 10);
      let hash = 0;
      for (let i = 0; i < today.length; i++) {
        hash = today.charCodeAt(i) + ((hash << 5) - hash);
      }
      return Math.abs(hash) % total;
    }
  },
};
</script>

